before.content:
const token = [REDACTED_CREDENTIAL] readToken(tokenPort);
try {
  const cookie = await exchangeToken(origin, token);
  await writeFrame(process.stdout, Buffer.from(JSON.stringify({ authenticated: true, cookie }), "utf8"));
} finally {
  token.fill(0);
}

after.content:
const token = [REDACTED_CREDENTIAL] readToken(tokenPort);
try {
  const cookie = await exchangeToken(origin, token);
  await writeFrame(process.stdout, Buffer.from(JSON.stringify({ cookies: [cookie], origins: [] }), "utf8"));
} finally {
  token.fill(0);
}
